def summ(name,c,y0,y1,oplabel='op margin'):
    yrs=[y for y in range(y0,y1+1) if y in c['rev']]
    rv=sum(c['rev'][y] for y in yrs); op=sum(c['op'][y] for y in yrs); ni=sum(c['ni'][y] for y in yrs)
    eq=[c['eq'][y] for y in range(y0-1,y1+1) if y in c['eq']]
    print(f"{name:4s} {y0}-{y1}: sum rev {rv:,.0f}  {oplabel} {op/rv*100:5.1f}%  sum NI {ni:,.0f}  avg ROE {ni/len(yrs)/(sum(eq)/len(eq))*100:5.1f}%  yrs {len(yrs)}")
    print('      by year op/rev %: '+' '.join(f"{y%100:02d}:{c['op'][y]/c['rev'][y]*100:.1f}" for y in yrs))
for (n,c,l) in [('FET',FET,'op margin'),('NOV',NOV,'op margin'),('SLB',SLB,'PRETAX margin'),('TS',TS,'op margin')]:
    summ(n,c,2015,2025,l)
for (n,c,l) in [('FET',FET,'op margin'),('NOV',NOV,'op margin'),('SLB',SLB,'PRETAX margin'),('TS',TS,'op margin')]:
    summ(n,c,2016,2020,l)
